// Verse text types and lookup, and the names of the structure and text files
// Verse texts generated by: npx tsx scripts/bundle-texts.ts

export interface VerseText {
  he: string;
  en: string;
}

export type VerseTexts = Record<string, Record<string, Record<string, VerseText>>>;
// Structure: { [book]: { [chapter]: { [verse]: { he, en } } } }

export const STRUCTURE_FILE = 'tanakh-structure.json';
export const TEXTS_FILE = 'all-texts.json';

export function getVerseText(
  verseTexts: VerseTexts,
  book: string,
  chapter: number,
  verse: number,
): VerseText | null {
  return verseTexts[book]?.[String(chapter)]?.[String(verse)] || null;
}
